<template><NuxtLayout><div class="page-heading"><div><div class="eyebrow">MONDAY MOTIVATION, EVERY DAY</div><h1>Your overview<span class="heading-dot">.</span></h1><p class="muted">A clear view of what matters right now.</p></div><button class="btn primary" @click="openTask">＋ New task</button></div>
<div class="stats-grid"><div class="stat-card stat-purple"><div class="stat-top"><span>All tasks</span><span class="stat-icon">☷</span></div><strong>{{tasks.counts.total}}</strong><small>Across your workspace</small><div class="stat-decoration">✦</div></div><div class="stat-card"><div class="stat-top"><span>In progress</span><span class="stat-icon blue">◷</span></div><strong>{{tasks.counts.progress}}</strong><small>Keep the momentum</small><div class="mini-track"><span :style="{width:progress+'%'}"/></div></div><div class="stat-card"><div class="stat-top"><span>Completed</span><span class="stat-icon green">✓</span></div><strong>{{tasks.counts.done}}</strong><small>Small wins add up</small><div class="stat-decoration green-text">✧</div></div><div class="stat-card"><div class="stat-top"><span>Projects</span><span class="stat-icon pink">▣</span></div><strong>{{projects.items.length}}</strong><small>Your ideas in motion</small><NuxtLink to="/projects" class="stat-link">View projects ↗</NuxtLink></div></div>
<div class="content-grid"><section class="panel tasks-panel"><div class="panel-head"><div><h2>Focus list <span class="count-badge">{{tasks.filtered.length}}</span></h2><p class="muted">The next steps toward your goals.</p></div><NuxtLink to="/tasks" class="text-link">See all tasks ↗</NuxtLink></div><div class="task-tabs"><button v-for="f in filters" :key="f.value" :class="{active:tasks.filter===f.value}" @click="tasks.filter=f.value">{{f.label}}</button></div><div v-if="tasks.loading" class="empty-state">Loading your tasks…</div><div v-else-if="!tasks.filtered.length" class="empty-state"><div class="empty-icon">✧</div><b>Nothing on your plate yet</b><p>Create a task and turn an idea into progress.</p><button class="btn soft" @click="openTask">＋ Add your first task</button></div><div v-else class="task-list"><article v-for="t in tasks.filtered.slice(0,7)" :key="t._id" class="task-row"><button class="check-circle" :class="{checked:t.status==='done'}" @click="toggle(t)">{{t.status==='done'?'✓':''}}</button><div class="task-main"><b :class="{completed:t.status==='done'}">{{t.title}}</b><small><span class="project-dot" :class="t.project?.color"/>{{t.project?.name || 'Project'}} <span v-if="t.dueDate">· Due {{date(t.dueDate)}}</span></small></div><span class="priority" :class="t.priority">{{t.priority}}</span><button class="more-btn" title="Edit task" @click="edit(t)">···</button></article></div></section><section class="panel projects-panel"><div class="panel-head"><div><h2>Your projects</h2><p class="muted">Big picture, little by little.</p></div><NuxtLink to="/projects" class="text-link">All ↗</NuxtLink></div><div v-if="!projects.items.length" class="empty-state compact"><div class="empty-icon">▣</div><b>Start with a project</b><p>Give your next idea a home.</p><NuxtLink to="/projects" class="btn soft">Create project</NuxtLink></div><NuxtLink v-for="p in projects.items.slice(0,4)" :key="p._id" to="/projects" class="project-mini"><div class="project-symbol" :class="p.color">✦</div><div class="project-mini-info"><b>{{p.name}}</b><small>{{p.openTasks || 0}} open tasks</small></div><span class="project-arrow">↗</span></NuxtLink><NuxtLink v-if="projects.items.length" to="/projects" class="add-project">＋ Add a project</NuxtLink><div class="quote-card"><span>✦ A gentle reminder</span><p>Progress is made one focused step at a time.</p><small>YOU'VE GOT THIS</small></div></section></div><TaskModal v-if="modal" :task="selected" :projects="projects.items" @close="closeModal" @save="saveTask"/></NuxtLayout></template>
<script setup>
const tasks=useTasksStore(),projects=useProjectsStore();const modal=ref(false),selected=ref(null);const filters=[{label:'All',value:'all'},{label:'To do',value:'todo'},{label:'In progress',value:'in-progress'},{label:'Done',value:'done'}];const progress=computed(()=>tasks.counts.total?Math.round(tasks.counts.done/tasks.counts.total*100):0);
onMounted(async()=>{await Promise.all([projects.fetchAll(),tasks.fetchAll()])});
function openTask(){selected.value=null;modal.value=true}function edit(t){selected.value=t;modal.value=true}function closeModal(){modal.value=false;selected.value=null}
async function saveTask(payload){if(selected.value)await tasks.update(selected.value._id,payload);else await tasks.create(payload);await Promise.all([projects.fetchAll(),tasks.fetchAll()]);closeModal()}
async function toggle(t){await tasks.update(t._id,{status:t.status==='done'?'todo':'done'});await Promise.all([projects.fetchAll(),tasks.fetchAll()])}
function date(d){return new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric'})}
</script>
